import{_ as e,c as t,o as r,a2 as i}from"./chunks/framework.Cqt7uvsz.js";const c=JSON.parse('{"title":"知识深度很重要","description":"","frontmatter":{},"headers":[],"relativePath":"interview/知识深度/x1-文本小节-知识深度很重要.md","filePath":"interview/知识深度/x1-文本小节-知识深度很重要.md","lastUpdated":1766579221000}'),l={name:"interview/知识深度/x1-文本小节-知识深度很重要.md"};function o(p,a,n,_,d,s){return r(),t("div",null,a[0]||(a[0]=[i('<h1 id="知识深度很重要" tabindex="-1">知识深度很重要 <a class="header-anchor" href="#知识深度很重要" aria-label="Permalink to &quot;知识深度很重要&quot;">​</a></h1><p>虽然我们日常干的都是“拧螺丝”“搬砖”的 CURD 工作，也体现不出什么难度，但自身的知识深度真的很重要。 工作是公司的、老板的，而能力是自己的，要区分开来。</p><h2 id="面试评级" tabindex="-1">面试评级 <a class="header-anchor" href="#面试评级" aria-label="Permalink to &quot;面试评级&quot;">​</a></h2><p>面试通过了，到底给你评定 P6 还是 P7 ？依据什么标准呢？</p><p>第一个因素不是你的技术，而是团队的预算，例如他们还有没有 P7 的名额。如果有，那可以考虑；如果没有，你能力再好也大不了 P7 。说这个因素是告诉你：如果你的平级不高，不一定是个人的因素。</p><p>第二个因素就是你的综合技术能力，而其中技术深度就是最关键的一个。如果你只是浮于表面，从未深入到原理或者源码层面，那就很难有说服力。</p><p>大厂不同级别的工资是不一样的，所以技术深度直接决定了你的“钱途”。</p><h2 id="难题攻坚" tabindex="-1">难题攻坚 <a class="header-anchor" href="#难题攻坚" aria-label="Permalink to &quot;难题攻坚&quot;">​</a></h2><p>在实际工作中，项目遇到了难题，老板可能会直接指派给你，也可能开会时叫人主动认领（此时你要量力而行，不要随意“抢答”）。无论何种方式，你接到了这样一个难题，是否能解决将决定你在领导心目中的形象。</p><p>我记得多年之前，我刚入职一家公司不久，就毛遂自荐搞定了一个系统卡顿的问题，很快就得到了领导的信任。信任，能带来很多好处</p><ul><li>绩效相对较高，年终奖多</li><li>偶尔划水摸鱼、迟到早退也无碍，只要不耽误工作。有了信任，这些都是瑕不掩瑜</li><li>评价其他人时，你的话语权更重</li></ul><p>最后，要解决难题，最需要的就是技术深度。否则你都看不清楚问题的本质，何谈解决？</p><h2 id="同事之间的影响力" tabindex="-1">同事之间的影响力 <a class="header-anchor" href="#同事之间的影响力" aria-label="Permalink to &quot;同事之间的影响力&quot;">​</a></h2><p>同事之间除了聊工作，还有很多私下随性沟通的机会，特别是午饭、午休时间。聊技术，永远是技术人员的话题。</p><p>再聊天过程中，大家都会发表个人的评论和观点。如果你有技术深度，看问题更加透彻，解释问题更加清晰，在同事眼中你自然就是一个“厉害的人”。</p><p>得到同事的认可和尊重，会增加工作的幸福感。人都有本能的社交需求。</p><h2 id="注意" tabindex="-1">注意 <a class="header-anchor" href="#注意" aria-label="Permalink to &quot;注意&quot;">​</a></h2><p>所谓技术深度，深了就不可能广。 所以，找准某一个方面深入进去即可，不可贪多。 而且，要找一个主流的技术栈，如 Vue React 相关的，要考虑技术的实际价值。</p>',18)]))}const u=e(l,[["render",o]]);export{c as __pageData,u as default};
